        if ((paginate == true))
        {
            return ccxt.BaseExchange.ToOHLCVList(await this.fetchPaginatedCallDeterministic("fetchOHLCV", symbol, since, limitVar,timeframeVar, paramsPaginate, 10000));
        }
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "instrument_name", (market.ContainsKey("id") ? market["id"] : null) },
            { "resolution", this.safeString(this.timeframes, timeframeVar, timeframeVar) },
        };
        IDictionary<string, object> marketInfo = this.safeDict(market, "info", new Dictionary<string, object>() {});
        if (this.isNativeDeribitCredentials() && (this.safeBool2(marketInfo, "is_cbe_routed", "is_csr", false) == true))
